    private void tampil() {
        if (!ceksukses) {
            ceksukses = true;
            this.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
            Valid.tabelKosongSmc(tabMode);
            LCount.setText("0");
            new SwingWorker<Void, Object[]>() {
                final String cari = TCari.getText().trim();

                @Override
                protected Void doInBackground() throws Exception {
                    try (PreparedStatement ps = koneksi.prepareStatement(
                        "select jam_masuk_smc.kode_shift, jam_masuk_smc.nama_shift, jam_masuk_smc.jam_masuk, jam_masuk_smc.jam_pulang, ifnull(set_kode_shift_smc.shift, '') as shift " +
                        "from jam_masuk_smc left join set_kode_shift_smc on jam_masuk_smc.kode_shift = set_kode_shift_smc.kode_shift " + (cari.isBlank() ? "" : "where (" +
                        "jam_masuk_smc.kode_shift like ? or jam_masuk_smc.nama_shift like ?) ") + "order by jam_masuk_smc.kode_shift"
                    )) {
                        int p = 0;
                        if (!cari.isBlank()) {
                            ps.setString(++p, "%" + cari + "%");
                            ps.setString(++p, "%" + cari + "%");
                        }
                        try (ResultSet rs = ps.executeQuery()) {
                            while (rs.next()) {
                                publish(new Object[] {
                                    false, rs.getString("kode_shift"), rs.getString("nama_shift"), rs.getString("jam_masuk"), rs.getString("jam_pulang"), rs.getString("shift")
                                });
                            }
                        }
                    }
                    return null;
                }

                @Override
                protected void process(List<Object[]> chunks) {
                    chunks.forEach(tabMode::addRow);
                }

                @Override
                protected void done() {
                    try {
                        get();
                    } catch (Exception e) {
                        System.out.println("Notif : " + e);
                    }
                    tabMode.fireTableDataChanged();
                    LCount.setText(tabMode.getRowCount() + "");
                    DlgJamMasukSMC.this.setCursor(Cursor.getDefaultCursor());
                    ceksukses = false;
                }
            }.execute();
        }
    }

