    private void getData() {
        int row = tbJadwal.getSelectedRow();
        if (row != -1) {
            kodeLama = tbJadwal.getValueAt(row, 1).toString();
            TKode.setText(kodeLama);
            TNama.setText(tbJadwal.getValueAt(row, 2).toString());
            cmbJam1.setSelectedItem(tbJadwal.getValueAt(row, 3).toString().substring(0, 2));
            cmbMnt1.setSelectedItem(tbJadwal.getValueAt(row, 3).toString().substring(3, 5));
            cmbDtk1.setSelectedItem(tbJadwal.getValueAt(row, 3).toString().substring(6, 8));
            cmbJam2.setSelectedItem(tbJadwal.getValueAt(row, 4).toString().substring(0, 2));
            cmbMnt2.setSelectedItem(tbJadwal.getValueAt(row, 4).toString().substring(3, 5));
            cmbDtk2.setSelectedItem(tbJadwal.getValueAt(row, 4).toString().substring(6, 8));
            if (tbJadwal.getValueAt(row, 5).toString().isEmpty()) {
                cmbShift.setSelectedItem(TANPA_SHIFT);
            } else {
                cmbShift.setSelectedItem(tbJadwal.getValueAt(row, 5).toString());
            }
        }
    }

    private boolean simpanMappingShift(String kode) {
        String shift = cmbShift.getSelectedItem().toString();
        if (TANPA_SHIFT.equals(shift)) {
            return Sequel.menghapustfSmc("set_kode_shift_smc", "kode_shift = ?", kode);
        }

        return Sequel.menghapustfSmc("set_kode_shift_smc", "shift = ? and kode_shift != ?", shift, kode) &&
            Sequel.executeRawSmc("insert into set_kode_shift_smc (shift, kode_shift) values (?, ?) on duplicate key update shift = values(shift)", shift, kode);
    }

    private Set<String> getKodeShift() {
        Set<String> kode = new LinkedHashSet<>();
        try (PreparedStatement ps = koneksi.prepareStatement("select kode_shift from jam_masuk_smc")) {
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    kode.add(rs.getString("kode_shift"));
                }
            }
        } catch (Exception e) {
            System.out.println("Notif : " + e);
        }
        return kode;
    }

    private String bacaTeks(Row baris, int kolom) {
        Cell cell = baris.getCell(kolom);
        if (cell == null) {
            return "";
        }
        if (CellType.NUMERIC.equals(cell.getCellType())) {
            return String.valueOf((long) cell.getNumericCellValue());
        }
        return cell.getStringCellValue().trim();
    }

    private String bacaJam(Row baris, int kolom) {
        Cell cell = baris.getCell(kolom);
        if (cell == null || !CellType.NUMERIC.equals(cell.getCellType())) {
            return "00:00:00";
        }

        int menit = (int) Math.round(cell.getNumericCellValue() * 1440d) % 1440;
        if (menit < 0) {
            menit = menit + 1440;
        }
        return String.format("%02d:%02d:00", menit / 60, menit % 60);
    }

